CREATE OR REPLACE FUNCTION public.guard_partner_property_group() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.business_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.partner_businesses b JOIN public.partner_accounts a ON a.id=b.partner_id WHERE b.id=NEW.business_id AND a.owner_user_id=NEW.manager_id) THEN RAISE EXCEPTION 'Property group must belong to the hotel owner'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER partner_property_group_guard BEFORE INSERT OR UPDATE OF business_id,manager_id ON public.partner_hotels FOR EACH ROW EXECUTE FUNCTION public.guard_partner_property_group();
CREATE OR REPLACE FUNCTION public.partner_delete_empty_draft(_hotel_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE h public.partner_hotels%ROWTYPE; BEGIN SELECT * INTO h FROM public.partner_hotels WHERE id=_hotel_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL OR h.manager_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not authorized to delete this property'; END IF; IF h.is_active IS TRUE OR h.onboarding_status <> 'draft' OR EXISTS (SELECT 1 FROM public.hotel_rooms WHERE hotel_id=_hotel_id) OR EXISTS (SELECT 1 FROM public.hotel_bookings WHERE hotel_id=_hotel_id) OR EXISTS (SELECT 1 FROM public.hotel_long_stays WHERE hotel_id=_hotel_id) OR EXISTS (SELECT 1 FROM public.hotel_availability_blocks WHERE hotel_id=_hotel_id) THEN RAISE EXCEPTION 'Only empty unpublished drafts can be deleted. Archive this property instead.'; END IF; DELETE FROM public.partner_hotels WHERE id=_hotel_id; END; $$;
REVOKE ALL ON FUNCTION public.partner_delete_empty_draft(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.partner_delete_empty_draft(uuid) TO authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['partner_hotels','hotel_rooms','hotel_bookings','hotel_reviews','hotel_ops_tasks','guest_portal_requests','partner_businesses','partner_accounts','hotel_availability_blocks'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t); END IF; END LOOP; END $$;